#!/usr/bin/env python
"""Detect a vLLM Gumbel watermark in text generated by a deployed InferenceService.

A Gumbel watermark is a keyed statistical bias in token sampling, not a field in the
inference response -- nothing in the OpenAI-compatible JSON reveals it. Recovering it
requires replaying the keyed PRF over the generated token IDs, so this script sends a
prompt to the ISVC, then runs ``GumbelWatermarkDetector`` to score the output.

The detector and the tokenizer live inside the predictor pod (``vllm`` and
``transformers`` are not dependencies of this repo), so the scoring step runs there via
``oc exec`` and only the verdict is returned.

Detection only succeeds when the detector settings match the ones the server was started
with: key, prf, algorithm and tokenizer. A mismatch looks exactly like "not watermarked".

Watermarking additionally requires stochastic sampling. vLLM silently skips it for
``temperature=0`` (greedy), so the default temperature here is deliberately non-zero.

Examples:
    # Verify a watermarked deployment, using greedy as a negative control
    ./scripts/detect_watermark.py --namespace wm-verify --key 42 --control

    # Score text you already have
    ./scripts/detect_watermark.py --namespace wm-verify --key 42 --samples 5
"""

from __future__ import annotations

import argparse
import json
import pathlib
import shlex
import subprocess
import sys
import tempfile

DETECTOR_SNIPPET = """
import json, sys
from vllm.v1.watermarking import GumbelWatermarkDetector

# argv: ids_json_path, key, prf. The ids are the exact tokens the server emitted
# (via return_token_ids), so no tokenizer round-trip is involved.
token_ids = json.load(open(sys.argv[1]))
result = GumbelWatermarkDetector(key=int(sys.argv[2]), prf=sys.argv[3]).detect(token_ids)
print("WATERMARK_RESULT " + json.dumps({
    "tokens": len(token_ids),
    "p_value": float(result.p_value),
    "is_watermarked": bool(result.is_watermarked),
}))
"""


def run(command: list[str], timeout: int = 900) -> str:
    """Run a command and return stdout, raising with stderr context on failure.

    Args:
        command: Argument vector to execute.
        timeout: Seconds to wait before giving up.

    Returns:
        The command's stdout.

    Raises:
        RuntimeError: If the command exits non-zero.
    """
    completed = subprocess.run(command, capture_output=True, text=True, timeout=timeout, check=False)
    if completed.returncode != 0:
        raise RuntimeError(f"command failed: {shlex.join(command)}\n{completed.stderr.strip()}")
    return completed.stdout


def predictor_pod(namespace: str) -> str:
    """Return the name of the first predictor pod in the namespace."""
    pods = run(
        command=[
            "oc",
            "get",
            "pods",
            "-n",
            namespace,
            "-l",
            "component=predictor",
            "-o",
            "jsonpath={.items[0].metadata.name}",
        ]
    ).strip()
    if not pods:
        raise RuntimeError(f"no predictor pod found in namespace '{namespace}'")
    return pods


def route_host(namespace: str) -> str:
    """Return the external route host for the namespace's InferenceService."""
    host = run(
        command=[
            "oc",
            "get",
            "route",
            "-n",
            namespace,
            "-o",
            "jsonpath={.items[0].spec.host}",
        ]
    ).strip()
    if not host:
        raise RuntimeError(f"no route found in namespace '{namespace}'")
    return host


def served_model_name(host: str) -> str:
    """Return the model id advertised by the server's /v1/models endpoint."""
    body = run(command=["curl", "-sk", f"https://{host}/v1/models"])
    return str(json.loads(body)["data"][0]["id"])


def generate(host: str, model: str, prompt: str, max_tokens: int, temperature: float) -> list[int]:
    """Send a completions request and return the exact token ids the server emitted.

    ``return_token_ids`` avoids a tokenizer round-trip: the detector scores the tokens
    the sampler actually chose rather than a re-encoding of the decoded text.

    Args:
        host: Route host of the InferenceService.
        model: Served model name.
        prompt: Prompt to send.
        max_tokens: Number of tokens to generate.
        temperature: Sampling temperature.

    Returns:
        The generated token ids.
    """
    payload = json.dumps({
        "model": model,
        "prompt": prompt,
        "max_tokens": max_tokens,
        "temperature": temperature,
        "return_token_ids": True,
    })
    body = run(
        command=[
            "curl",
            "-sk",
            f"https://{host}/v1/completions",
            "-H",
            "Content-Type: application/json",
            "-d",
            payload,
        ]
    )
    choice = json.loads(body)["choices"][0]
    token_ids = choice.get("token_ids")
    if not token_ids:
        raise RuntimeError("server did not return token_ids; this build may not support return_token_ids")
    return [int(token) for token in token_ids]


def detect(namespace: str, pod: str, token_ids: list[int], key: int, prf: str) -> dict[str, object]:
    """Score token ids for a Gumbel watermark inside the predictor pod.

    Args:
        namespace: Namespace holding the predictor pod.
        pod: Predictor pod name.
        token_ids: Exact token ids the server emitted.
        key: Watermark key the server was started with.
        prf: Pseudo-random function the server was started with.

    Returns:
        Mapping with ``tokens``, ``p_value`` and ``is_watermarked``.
    """
    with tempfile.TemporaryDirectory() as workdir:
        local_ids = pathlib.Path(workdir) / "ids.json"
        local_ids.write_text(data=json.dumps(token_ids))
        local_script = pathlib.Path(workdir) / "detector.py"
        local_script.write_text(data=DETECTOR_SNIPPET)

        for source, destination in ((local_ids, "/tmp/wm_ids.json"), (local_script, "/tmp/wm_detector.py")):
            run(command=["oc", "cp", str(source), f"{namespace}/{pod}:{destination}", "-c", "kserve-container"])

        output = run(
            command=[
                "oc",
                "exec",
                "-n",
                namespace,
                pod,
                "-c",
                "kserve-container",
                "--",
                "python",
                "/tmp/wm_detector.py",
                "/tmp/wm_ids.json",
                str(key),
                prf,
            ]
        )

    marker = "WATERMARK_RESULT "
    for line in output.splitlines():
        if line.startswith(marker):
            return dict(json.loads(line.removeprefix(marker)))
    raise RuntimeError(f"detector produced no result:\n{output}")


def main() -> int:
    """Entry point: generate (or load) text, score it, and report the verdict."""
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--namespace", required=True, help="Namespace of the deployed InferenceService")
    parser.add_argument("--key", type=int, required=True, help="Watermark key the server was started with")
    parser.add_argument("--prf", default="philox", help="PRF the server was started with (default: philox)")
    parser.add_argument(
        "--prompt",
        default="Write a detailed essay about ocean currents, volcanoes, jazz music and medieval trade routes.",
        help="Prompt used to generate text to score. Varied prose detects better than repetitive prose",
    )
    parser.add_argument("--max-tokens", type=int, default=350, help="Tokens to generate; more tokens, more power")
    parser.add_argument(
        "--temperature",
        type=float,
        default=0.8,
        help="Sampling temperature. Must be > 0; greedy decoding cannot be watermarked",
    )
    parser.add_argument(
        "--samples",
        type=int,
        default=3,
        help="Generations to score. Per-sample strength varies, so a single sample can miss a real watermark",
    )
    parser.add_argument(
        "--control",
        action="store_true",
        help="Also score a temperature=0 generation, which must come back not watermarked",
    )
    args = parser.parse_args()

    if args.temperature <= 0:
        parser.error("--temperature must be > 0; vLLM skips watermarking for greedy decoding")

    pod = predictor_pod(namespace=args.namespace)
    host = route_host(namespace=args.namespace)
    model = served_model_name(host=host)
    print(f"namespace={args.namespace} pod={pod}\nmodel={model} key={args.key} prf={args.prf}\n")

    samples: list[tuple[str, list[int]]] = [
        (
            f"temperature={args.temperature} #{index + 1}",
            generate(
                host=host,
                model=model,
                prompt=args.prompt,
                max_tokens=args.max_tokens,
                temperature=args.temperature,
            ),
        )
        for index in range(args.samples)
    ]
    if args.control:
        samples.append((
            "temperature=0 (control)",
            generate(host=host, model=model, prompt=args.prompt, max_tokens=args.max_tokens, temperature=0.0),
        ))

    watermarked_count = 0
    control_watermarked = False
    for label, token_ids in samples:
        result = detect(namespace=args.namespace, pod=pod, token_ids=token_ids, key=args.key, prf=args.prf)
        verdict = "WATERMARKED" if result["is_watermarked"] else "not watermarked"
        print(f"{label}: tokens={result['tokens']}  p_value={result['p_value']:.6g}  -> {verdict}")
        if label.startswith("temperature=0 "):
            control_watermarked = bool(result["is_watermarked"])
        elif result["is_watermarked"]:
            watermarked_count += 1

    print(f"\nwatermarked {watermarked_count}/{args.samples} sampled generations")
    if control_watermarked:
        print("WARNING: the greedy control scored as watermarked - treat positives as suspect")
        return 1
    if watermarked_count == 0:
        print("No watermark detected. Check the key, prf and algorithm match how the server was started.")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
